CREATE TABLE public.services (id text PRIMARY KEY, name text NOT NULL, category text NOT NULL, description text NOT NULL, status text NOT NULL DEFAULT 'coming_soon' CHECK (status IN ('available','coming_soon')), display_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.services TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.services TO authenticated;
GRANT ALL ON public.services TO service_role;
ALTER TABLE public.services ENABLE ROW LEVEL SECURITY;
CREATE POLICY "public service catalogue" ON public.services FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "admins manage services" ON public.services FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.care_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), full_name text NOT NULL CHECK (length(trim(full_name)) BETWEEN 1 AND 300), email text NOT NULL, phone text, country text, existing_family text CHECK (existing_family IN ('Yes','No')), parent_name text, parent_location text, service_id text NOT NULL REFERENCES public.services(id), urgency text CHECK (urgency IN ('Today','This week','Within a month','Just exploring')), message text, consent boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'new' CHECK (status IN ('new','contacted','quoted','booked','completed','cancelled','waitlist')), notes text);
GRANT INSERT ON public.care_requests TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.care_requests TO authenticated;
GRANT ALL ON public.care_requests TO service_role;
ALTER TABLE public.care_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "public care submissions" ON public.care_requests FOR INSERT TO anon, authenticated WITH CHECK (notes IS NULL AND ((status = 'new' AND consent = true AND length(trim(phone)) >= 8 AND length(trim(parent_name)) > 0 AND length(trim(parent_location)) > 0 AND EXISTS (SELECT 1 FROM public.services WHERE id = service_id AND services.status = 'available')) OR (status = 'waitlist' AND consent = false AND EXISTS (SELECT 1 FROM public.services WHERE id = service_id AND services.status = 'coming_soon'))));
CREATE POLICY "admins manage care requests" ON public.care_requests FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE INDEX care_requests_created_idx ON public.care_requests(created_at DESC);
CREATE INDEX care_requests_filters_idx ON public.care_requests(service_id,status,urgency);
CREATE TABLE public.physiotherapist_applicants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), full_name text NOT NULL, email text NOT NULL, phone text NOT NULL, location text NOT NULL, registration_number text NOT NULL CHECK (length(trim(registration_number)) > 0), years_experience text, details jsonb NOT NULL DEFAULT '{}', files jsonb NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'Applied' CHECK (status IN ('Applied','Documents checked','Verified','Interviewed','Active pool','Not progressing')), notes text);
GRANT INSERT ON public.physiotherapist_applicants TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.physiotherapist_applicants TO authenticated;
GRANT ALL ON public.physiotherapist_applicants TO service_role;
ALTER TABLE public.physiotherapist_applicants ENABLE ROW LEVEL SECURITY;
CREATE POLICY "public physiotherapist application" ON public.physiotherapist_applicants FOR INSERT TO anon, authenticated WITH CHECK (status = 'Applied' AND notes IS NULL AND length(trim(details->>'Reference 1')) > 0 AND length(trim(details->>'Reference 2')) > 0);
CREATE POLICY "admins manage physiotherapist applications" ON public.physiotherapist_applicants FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.lab_partner_applicants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), full_name text NOT NULL, email text NOT NULL, phone text NOT NULL, location text NOT NULL, registration_number text, years_experience text, details jsonb NOT NULL DEFAULT '{}', files jsonb NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'Applied' CHECK (status IN ('Applied','Documents checked','Verified','Interviewed','Active pool','Not progressing')), notes text);
GRANT INSERT ON public.lab_partner_applicants TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.lab_partner_applicants TO authenticated;
GRANT ALL ON public.lab_partner_applicants TO service_role;
ALTER TABLE public.lab_partner_applicants ENABLE ROW LEVEL SECURITY;
CREATE POLICY "public lab application" ON public.lab_partner_applicants FOR INSERT TO anon, authenticated WITH CHECK (status = 'Applied' AND notes IS NULL);
CREATE POLICY "admins manage lab applications" ON public.lab_partner_applicants FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.pharmacy_partner_applicants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), full_name text NOT NULL, email text NOT NULL, phone text NOT NULL, location text NOT NULL, registration_number text NOT NULL CHECK (length(trim(registration_number)) > 0), years_experience text, details jsonb NOT NULL DEFAULT '{}', files jsonb NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'Applied' CHECK (status IN ('Applied','Documents checked','Verified','Interviewed','Active pool','Not progressing')), notes text);
GRANT INSERT ON public.pharmacy_partner_applicants TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.pharmacy_partner_applicants TO authenticated;
GRANT ALL ON public.pharmacy_partner_applicants TO service_role;
ALTER TABLE public.pharmacy_partner_applicants ENABLE ROW LEVEL SECURITY;
CREATE POLICY "public pharmacy application" ON public.pharmacy_partner_applicants FOR INSERT TO anon, authenticated WITH CHECK (status = 'Applied' AND notes IS NULL);
CREATE POLICY "admins manage pharmacy applications" ON public.pharmacy_partner_applicants FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));